const response = await client.shippingSettings.getShippingSettings();
const settings = response.map.shipping_settings;
console.log(settings.default_shipping_profile?.name, settings.default_delivery_profile?.name);
console.log(settings.enable_shipping_default_tax, settings.enable_delivery_default_tax);
